 #[test]fn actual_closure_writer_first_1450_after_create_or_truncate_reprepares_before_return_and_recovers(){let _context=super::super::control::bind_with_deadline(super::super::control::Cancellation::default(),Instant::now()+Duration::from_secs(120));for existing in[false,true]{let(mut host,request,binding)=fixture(if existing{"sem-closure-truncate-1450"}else{"sem-closure-create-1450"},"/datum/utility_first_io\n",Question::Closure{write:true});let path=binding.root.join(crate::runner_host::sem_closure_capture::RELATIVE);if existing{fs::write(&path,b"actual previous authored report\n").unwrap()}let mut seen=0;let error=host.stage_native_sem_utility_using(request.clone(),&binding,&mut|event|{if matches!((existing,event),(true,crate::native_author_fix_transaction::Event::AfterTruncate)|(false,crate::native_author_fix_transaction::Event::AfterCreate)){seen+=1;return Err(io::Error::from_raw_os_error(1450))}Ok(())}).err().expect("actual attempted writer IO must refuse the terminal");assert_eq!(seen,1);let failed=error.downcast_ref::<crate::native_fix::FailedMutation>().expect("same existing mutation owner retains attempt and recovery");assert!(failed.may_have_changed);assert!(failed.recovered,"same-host actual preparation must finish before first IO returns");let mut source:&dyn std::error::Error=error.as_ref();let mut actual=None;loop{if let Some(io)=source.downcast_ref::<io::Error>(){actual=Some(io.raw_os_error());break}match source.source(){Some(next)=>source=next,None=>break}}assert_eq!(actual,Some(Some(1450)));assert_eq!(fs::read(&path).unwrap(),b"");let(exit,out,_)=run(&mut host,request,&binding);assert_eq!(exit,0);assert_eq!(out,format!("wrote {}\n",path.display()));assert!(!fs::read(&path).unwrap().is_empty());}}
 #[test]fn actual_utility_same_work_metadata_pressure_refuses_before_target_mutation_then_refunds(){let _context=super::super::control::bind_with_deadline(super::super::control::Cancellation::default(),Instant::now()+Duration::from_secs(120));let(mut host,request,binding)=fixture("sem-closure-real-pressure","/datum/utility_pressure\n",Question::Closure{write:true});let path=binding.root.join(crate::runner_host::sem_closure_capture::RELATIVE);fs::write(&path,b"preserve authored bytes").unwrap();let(mut low,mut high)=(0usize,128*1024*1024usize);while low<high{let probe=low+(high-low).div_ceil(2);match host.source_arena_work().reserve(probe){Ok(lease)=>{drop(lease);low=probe},Err(actual)if actual.kind()==io::ErrorKind::OutOfMemory=>high=probe-1,Err(actual)=>panic!("actual work admission: {actual}")}}assert!(low>8192);let pressure=host.source_arena_work().reserve(low-8).unwrap();let mut attempted=0;let error=host.stage_native_sem_utility_using(request.clone(),&binding,&mut|_|{attempted+=1;Ok(())}).err().expect("actual same-work pressure must refuse");assert_eq!(error.downcast_ref::<io::Error>().unwrap().kind(),io::ErrorKind::OutOfMemory);assert_eq!(attempted,0);assert_eq!(fs::read(&path).unwrap(),b"preserve authored bytes");drop(pressure);let(exit,_,_)=run(&mut host,request,&binding);assert_eq!(exit,0);}

