 const CLOSURE_ROOT_SOURCE:&str="/datum/closure_lineage\n    var/value\n    proc/set_value(next)\n        value=next\n    proc/read_value()\n        return value\n    proc/draw()\n        return read_value()\n    proc/touch()\n        src.set_value(1)\n";
 #[test]
 fn actual_closure_callables_typed_setters_and_read_questions_share_the_real_operation_root(){
  let _context=super::super::control::bind_with_deadline(super::super::control::Cancellation::default(),Instant::now()+Duration::from_secs(120));
  let(mut host,request,binding)=fixture("sem-closure-operation-root",CLOSURE_ROOT_SOURCE,Question::Closure{write:false});
  let(exit,out,err)=run(&mut host,request.clone(),&binding);assert_eq!(exit,0);assert!(out.starts_with("# Reads closure\n"));assert!(out.contains("| legacy walk |")&&out.contains("| closed walk |"));assert!(err.contains("decls: "));assert!(!binding.root.join(crate::runner_host::sem_closure_capture::RELATIVE).exists());
  let(again,second,_)=run(&mut host,request,&binding);assert_eq!(again,0);assert_eq!(second,out,"same host/current source must repeat the real typed/query/report fold");
 }
 #[test]
 fn actual_closure_callable_report_preserves_first_1450_and_same_host_recovers_without_authored_write(){
  let _context=super::super::control::bind_with_deadline(super::super::control::Cancellation::default(),Instant::now()+Duration::from_secs(120));
  let(mut host,request,binding)=fixture("sem-closure-root-first-io",CLOSURE_ROOT_SOURCE,Question::Closure{write:false});
  let report=host.stage_native_sem_utility(request.clone(),&binding).unwrap();
  struct Failed{calls:usize}impl io::Write for Failed{fn write(&mut self,_:&[u8])->io::Result<usize>{self.calls+=1;Err(io::Error::from_raw_os_error(1450))}fn flush(&mut self)->io::Result<()>{Ok(())}}
  let mut writer=Failed{calls:0};let error=report.publish(&mut writer,&mut Vec::new()).unwrap_err();assert_eq!(error.downcast_ref::<io::Error>().unwrap().raw_os_error(),Some(1450));assert_eq!(writer.calls,1);assert!(!binding.root.join(crate::runner_host::sem_closure_capture::RELATIVE).exists());
  let(exit,out,_)=run(&mut host,request,&binding);assert_eq!(exit,0);assert!(out.starts_with("# Reads closure\n"));
 }

 #[test]fn actual_utility_marker_prelude_uses_current_raw_pages_while_semantic_child_keeps_no_analyze_raw(){
  let _context=super::super::control::bind_with_deadline(super::super::control::Cancellation::default(),Instant::now()+Duration::from_secs(120));
  let source="#define CAPABILITIES(x)\nCAPABILITIES(/datum/native_utility)\n/datum/native_utility\n    var/value\n";
  let(mut host,request,binding)=fixture("sem-utility-authentic-marker-pages",source,Question::Help);
  let report=host.stage_native_sem_utility(request.clone(),&binding).unwrap();
  let query_state=host.query_state();let state=query_state.lock().unwrap();let snapshot=state.snapshot.as_ref().unwrap();
  let count=report.inputs.with_context(||snapshot.with_original_utility_model(crate::policy_request::WorkspaceAuxiliaryQuestion::SemReads,true,|policy,root,_budget,_work,_body,markers|{
   let file=policy.file(&root.join("code/probe.dm")).unwrap();
   assert!(matches!(file.view(dm_analysis::policy_inputs::TextView::AnalyzeRaw),Err(dm_analysis::policy_inputs::CaptureError::MissingView{..})),"semantic child stays source-only; raw must come from actual workspace pages");
   let(count,_elapsed)=markers.expect("genuine raw traversal finished before the held source-work ledger loan");Ok(count)
  })).unwrap();assert_eq!(count,1);
  report.inputs.with_context(||snapshot.with_original_utility_model(crate::policy_request::WorkspaceAuxiliaryQuestion::SemReads,false,|_policy,_root,_budget,work,_body,markers|{
   assert!(markers.is_none(),"resource-only consumers do not acquire an unsolicited raw marker traversal");
   let credit=work.reserve(32)?;assert_eq!(credit.reserved_bytes(),32);drop(credit);Ok(())
  })).unwrap();drop(state);
  fs::write(binding.root.join("code/probe.dm"),format!("{source}CAPABILITIES(/datum/native_utility)\n")).unwrap();assert!(report.require_current().is_err());drop(report);
  let(exit,_,err)=run(&mut host,request,&binding);assert_eq!(exit,0);assert!(err.contains("(2 markers)"),"actual current source mutation must change the counted rows: {err}");
 }
